def is_balanced(text: str) -> bool:
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}

    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

    return not stack
